/* The Claude spark: an 8-bit alpha mask taken from the 256 px icon of the installed Claude desktop app
 * (generated by tools\logo_mask.py into logo_mask.h), scaled at run time with an area-average filter.
 * No window code: the test program links this file. */
#ifndef CTU_LOGO_H
#define CTU_LOGO_H

/* Side length of the stored square mask in pixels. */
int ctu_logo_n(void);
/* The stored mask, ctu_logo_n() * ctu_logo_n() bytes, row by row, 0 = empty, 255 = spark. */
const unsigned char *ctu_logo_mask(void);
/* Fill colour of the spark (the orange of the source icon). */
void ctu_logo_color(unsigned char *r, unsigned char *g, unsigned char *b);
/* Scales the mask to size x size (1..256) with an area-average (box) filter into out (size * size bytes).
 * Returns the number of non-zero output pixels, or -1 on a bad size or no memory. */
int ctu_logo_scale(int size, unsigned char *out);

#endif
